parameters.jsCode:
// PDF Text-Extraktion aus Supabase Storage
// Für jede signierte URL: HTTP GET → Binary → Text extrahieren
// HINWEIS: In n8n Pro kann man binary data mit pdfjs verarbeiten
// Hier wird ein strukturierter Prompt für Mistral vorbereitet

const leadData = $('Lead aus Supabase laden').item.json;
const signedUrls = $input.first().json;

// Vereinfachter Ansatz: Prüfe welche Dateien existieren
const fileList = signedUrls
  .filter(f => f.signedURL !== null)
  .map(f => f.path.split('/')[1].replace('.pdf', ''));

const hatSchufa = fileList.includes('schufa');
const hatEntgelt1 = fileList.includes('entgelt_1');
const hatEntgelt2 = fileList.includes('entgelt_2');
const hatEntgelt3 = fileList.includes('entgelt_3');

return [{
  json: {
    leadUuid: $('Webhook von Landing Page').item.json.leadUuid,
    leadName: leadData.name,
    inseratId: leadData.inserat_id,
    email: $('Webhook von Landing Page').item.json.email,
    telefon: $('Webhook von Landing Page').item.json.telefon,
    hatSchufa,
    hatEntgelt1,
    hatEntgelt2,
    hatEntgelt3,
    anzahlEntgeltnachweise: [hatEntgelt1, hatEntgelt2, hatEntgelt3].filter(Boolean).length,
    fileList,
    mistralPrompt: `Analysiere die hochgeladenen Dokumente für eine Mietbewerbung.

Vorhandene Dokumente: ${fileList.join(', ')}

Prüfe ausschließlich die VOLLSTÄNDIGKEIT der Unterlagen (kein Qualitätsurteil über die Person):
1. Ist eine Schufa-Auskunft vorhanden? (Ja/Nein)
2. Wie viele Einkommensnachweise sind vorhanden? (0-3, benötigt werden 3 Monate)
3. Sind die Mindestanforderungen erfüllt? (Schufa + mind. 1 Entgeltnachweis)

Antworte NUR mit JSON:
{
  "schufa_vorhanden": boolean,
  "anzahl_entgeltnachweise": number,
  "mindestanforderung_erfuellt": boolean,
  "fehlende_dokumente": ["liste"],
  "vollstaendigkeits_score": 0-100
}`
  }
}];

parameters.jsonBody:
={
  "model": "mistral-small-latest",
  "messages": [
    {
      "role": "system",
      "content": "Du bist ein Assistent einer Hausverwaltung. Du prüfst ausschließlich die formale Vollständigkeit von Bewerbungsunterlagen. Du machst KEIN Qualitätsurteil über Personen. Antworte immer nur mit validem JSON."
    },
    {
      "role": "user", 
      "content": "{{ $json.mistralPrompt }}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 500
}

parameters.jsCode:
const mistralResponse = $input.first().json;
const content = mistralResponse.choices[0].message.content;

let analyse;
try {
  // JSON aus Mistral-Antwort extrahieren
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  analyse = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch(e) {
  analyse = {
    schufa_vorhanden: false,
    anzahl_entgeltnachweise: 0,
    mindestanforderung_erfuellt: false,
    fehlende_dokumente: ['Parsing-Fehler'],
    vollstaendigkeits_score: 0
  };
}

const prevData = $('Dokumente als Text extrahieren').item.json;

return [{
  json: {
    ...prevData,
    analyse,
    bereit_fuer_hitl: analyse.mindestanforderung_erfuellt,
    mistral_tokens: mistralResponse.usage?.total_tokens || 0
  }
}];
